using System;
using System.IO;
using System.Linq;
using System.Drawing;
using System.Windows.Forms;
using System.Collections.Generic;
namespace JingChu {
public partial class MainForm {
 static IEnumerable<Control> Descendants(Control c){foreach(Control child in c.Controls){yield return child;foreach(var nested in Descendants(child))yield return nested;}}
 void MenuAction(ContextMenuStrip menu,string title,Action action,Func<bool> allowed){var entry=new ToolStripMenuItem(title);entry.Click+=(s,e)=>{if(!busy)try{action();}catch(Exception ex){BrandDialogs.Show(ex.Message,"操作未完成");}};menu.Items.Add(entry);menu.Opening+=(s,e)=>entry.Enabled=!busy&&allowed();}
 static void CheckSelection(ListView list){var selected=list.SelectedItems.Cast<ListViewItem>().ToArray();foreach(ListViewItem r in list.Items)r.Checked=selected.Contains(r);}
 ContextMenuStrip ItemMenu(ListView list){list.MultiSelect=true;var menu=new ContextMenuStrip{Font=Font,BackColor=Color.White,ForeColor=Look.Ink,ShowImageMargin=false};list.ContextMenuStrip=menu;list.MouseDown+=(s,e)=>{if(e.Button!=MouseButtons.Right)return;var hit=list.GetItemAt(e.X,e.Y);if(hit==null){foreach(ListViewItem r in list.SelectedItems.Cast<ListViewItem>().ToArray())r.Selected=false;}else if(!hit.Selected){foreach(ListViewItem r in list.SelectedItems.Cast<ListViewItem>().ToArray())r.Selected=false;hit.Selected=true;hit.Focused=true;}};return menu;}
 void CommonMenu(ContextMenuStrip menu,ListView list,string name){menu.Items.Add(new ToolStripSeparator());MenuAction(menu,"查看所选详情",()=>ViewReport(name,string.Join(Environment.NewLine+Environment.NewLine,list.SelectedItems.Cast<ListViewItem>().Select(x=>string.Join(Environment.NewLine,x.SubItems.Cast<ListViewItem.ListViewSubItem>().Select(y=>y.Text))))),()=>list.SelectedItems.Count>0);MenuAction(menu,"复制所选内容",()=>Clipboard.SetText(string.Join(Environment.NewLine,list.SelectedItems.Cast<ListViewItem>().Select(x=>string.Join("\t",x.SubItems.Cast<ListViewItem.ListViewSubItem>().Select(y=>y.Text))))),()=>list.SelectedItems.Count>0);MenuAction(menu,"导出列表 CSV",()=>ExportList(list,name),()=>list.Items.Count>0);MenuAction(menu,"全选列表行",()=>{foreach(ListViewItem r in list.Items)r.Selected=true;},()=>list.Items.Count>0);if(list.CheckBoxes){MenuAction(menu,"勾选所选行",()=>{foreach(ListViewItem r in list.SelectedItems)r.Checked=true;},()=>list.SelectedItems.Count>0);MenuAction(menu,"取消所选行勾选",()=>{foreach(ListViewItem r in list.SelectedItems)r.Checked=false;},()=>list.SelectedItems.Count>0);}}
 void SetupMenus(){var fm=ItemMenu(files);Func<bool> hasFiles=()=>files.SelectedItems.Count>0;MenuAction(fm,"预览所选目标",()=>{var a=files.SelectedItems.Cast<ListViewItem>().Select(x=>(string)x.Tag).ToArray();Work("预览所选目标",t=>{var report=Engine.Preview(a,t);BeginInvoke(new Action(()=>ViewReport("目标预览",report)));});},hasFiles);MenuAction(fm,"查询所选目标占用",()=>{CheckSelection(files);FindLocks();},hasFiles);MenuAction(fm,"重命名 / 移动",MoveOne,()=>files.SelectedItems.Count==1);MenuAction(fm,"所选目标移入回收站",()=>{CheckSelection(files);DeleteFiles(0);},hasFiles);MenuAction(fm,"永久删除所选目标",()=>{CheckSelection(files);DeleteFiles(1);},hasFiles);MenuAction(fm,"重启后删除所选目标",()=>{CheckSelection(files);DeleteFiles(2);},hasFiles);MenuAction(fm,"从列表移除所选行",()=>{foreach(ListViewItem row in files.SelectedItems.Cast<ListViewItem>().ToArray())row.Remove();},hasFiles);CommonMenu(fm,files,"文件列表");
  var am=ItemMenu(apps);MenuAction(am,"卸载勾选软件（无勾选时用选中行）",Uninstall,()=>checkedAppIds.Count>0||apps.SelectedItems.Count>0);MenuAction(am,"查看安装目录",()=>{var a=SelectedApp();if(a!=null){if(!Directory.Exists(a.Location))throw new Exception("安装目录未登记或不存在。");System.Diagnostics.Process.Start("explorer.exe",Engine.Quote(a.Location));}},()=>apps.SelectedItems.Count==1);MenuAction(am,"扫描所选软件残留",()=>{var a=SelectedApp();if(a!=null){keyword.Text=Engine.ResidualName(a.Name);ShowPage(3);ScanResidue();}},()=>apps.SelectedItems.Count==1);MenuAction(am,"刷新软件列表",ReloadApps,()=>true);CommonMenu(am,apps,"软件列表");
  var rm=ItemMenu(residue);MenuAction(rm,"清理所选候选项（确认后）",()=>{CheckSelection(residue);CleanResidue();},()=>residue.SelectedItems.Count>0);CommonMenu(rm,residue,"残留候选项");
  var sm=ItemMenu(smart);MenuAction(sm,"清理所选空间项目（确认后）",()=>{CheckSelection(smart);CleanSmart();},()=>smart.SelectedItems.Cast<ListViewItem>().Any(x=>x.Tag is CleanCandidate));MenuAction(sm,"发送所选项目到文件处理",()=>{AddFiles(smart.SelectedItems.Cast<ListViewItem>().Select(x=>x.Tag).OfType<CleanCandidate>().Select(x=>x.Path));ShowPage(1);},()=>smart.SelectedItems.Cast<ListViewItem>().Any(x=>x.Tag is CleanCandidate));MenuAction(sm,"重新扫描",ScanSmart,()=>true);CommonMenu(sm,smart,"空间整理");
  var stm=ItemMenu(startup);MenuAction(stm,"禁用所选启动项",()=>ChangeStartup(false),()=>startup.SelectedItems.Count==1);MenuAction(stm,"恢复所选文件启动项",()=>ChangeStartup(true),()=>startup.SelectedItems.Count==1&&startup.SelectedItems[0].Tag is StartupFile&&((StartupFile)startup.SelectedItems[0].Tag).Disabled);MenuAction(stm,"刷新启动项",LoadStartup,()=>true);CommonMenu(stm,startup,"启动项");
  var bm=ItemMenu(backups);MenuAction(bm,"恢复所选注册表备份（确认后）",()=>Restore((string)backups.SelectedItems[0].Tag),()=>backups.SelectedItems.Count==1);MenuAction(bm,"查看所选备份内容",()=>ViewReport("注册表备份内容",File.ReadAllText((string)backups.SelectedItems[0].Tag)),()=>backups.SelectedItems.Count==1);MenuAction(bm,"打开备份目录",()=>OpenFolder(Engine.BackupDir),()=>true);MenuAction(bm,"刷新备份",LoadBackups,()=>true);CommonMenu(bm,backups,"注册表备份");
  foreach(var page in pages){var background=new ContextMenuStrip{Font=Font,ShowImageMargin=false};MenuAction(background,"返回概览",()=>ShowPage(0),()=>true);MenuAction(background,"打开备份目录",()=>OpenFolder(Engine.BackupDir),()=>true);MenuAction(background,"打开日志目录",()=>OpenFolder(Engine.LogDir),()=>true);MenuAction(background,"关于景·除",()=>ShowPage(7),()=>true);page.ContextMenuStrip=background;foreach(var c in Descendants(page))if(c.ContextMenuStrip==null&&!(c is TextBoxBase)&&!(c is ListView))c.ContextMenuStrip=background;}
 }
}
public static partial class Engine {
 public static List<InstalledApp> PrepareUninstallQueue(IEnumerable<InstalledApp> selected){var seen=new HashSet<string>(StringComparer.OrdinalIgnoreCase);return selected.Where(x=>x!=null&&seen.Add((x.Name??"")+"|"+(x.Command??"").Trim())).ToList();}
}
}
